css='''<style>:root{--pea:#74045f;--gold:#c7911b;--green:#13895b;--red:#e8343f}body{background:#f3f4f8;color:#252b3b;font-size:17px}header{height:74px;background:white;border-bottom:3px solid var(--pea);display:flex;align-items:center;justify-content:space-between;padding:0 30px;gap:20px;position:sticky;top:0;z-index:10}.brands{display:flex;align-items:center;gap:22px}.pea{display:flex;align-items:center;gap:10px;color:var(--pea);font-weight:800}.pea img{height:48px;width:48px;object-fit:contain}.st{color:var(--green);font-weight:800;font-size:23px;line-height:1}.st small{display:block;font-size:12px;letter-spacing:2px;margin-top:5px;color:var(--green)}.se{font-size:24px;font-weight:800;letter-spacing:-1px;color:#333}.se span{color:var(--red)}.period{color:#717889;font-size:14px}main{max-width:1440px;padding:28px}h1{margin:4px 0 12px;font-size:32px}h2{font-size:23px}section{border-color:#e4e6ed;box-shadow:0 2px 10px #22222203}.cards{grid-template-columns:repeat(6,1fr);gap:12px}.card{padding:20px 16px;border-top:3px solid var(--pea);border-radius:12px;font-size:15px}.card:nth-child(1),.card:nth-child(4){border-top-color:var(--green)}.card:nth-child(3){border-top-color:var(--gold)}.card:nth-child(5){border-top-color:var(--red)}.card strong{font-size:25px;color:var(--pea)}nav{display:flex;gap:8px;flex-wrap:wrap;margin:22px 0}nav a{padding:10px 17px;border-radius:9px;background:white;border:1px solid #e1dce4;text-decoration:none;color:var(--pea);font-weight:600}nav a:hover{background:#f4e7f1}.split{display:grid;grid-template-columns:340px 1fr;gap:18px}.flowbox{display:grid;gap:18px}.flowrow{padding:18px;border-radius:12px;background:#f6f7fa;border-left:4px solid var(--green)}.flowrow:nth-child(2){border-color:var(--gold)}.flowrow:nth-child(3){border-color:var(--pea)}.flowrow:nth-child(4){border-color:var(--red)}.flowrow strong{display:block;font-size:23px;margin-top:6px}.flowrow small{font-size:13px}.bar{height:22px;border-radius:7px;background:#e9eaf0;overflow:hidden;display:flex;margin:12px 0 20px}.bar span{display:block;height:100%}section{scroll-margin-top:100px}svg{height:290px}select,input{background:white;color:#343c4f;border-color:#dcdde4}th{background:#f5edf3;color:var(--pea);position:sticky;top:0}td{white-space:nowrap}.scroll td:last-child{white-space:normal;min-width:200px}.note{background:#fff8e8;font-size:15px;line-height:1.6}.legend{font-size:14px}.mini{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.mini div{padding:18px;background:#f6f7fa;border-radius:10px}.mini strong{display:block;font-size:24px;color:var(--pea);margin-top:8px}details{margin-top:15px;font-size:15px;line-height:1.7}footer{padding:24px;color:#747988;font-size:14px}.chartbox{min-width:600px}.data-note{font-size:14px;color:#72798a}@media(max-width:1000px){.cards{grid-template-columns:repeat(3,1fr)}.split{grid-template-columns:1fr}}@media(max-width:650px){header{padding:0 15px;height:68px}.brands{gap:12px}.pea img{height:38px;width:38px}.pea b{display:none}.st,.se{font-size:19px}.period{display:none}.cards{grid-template-columns:repeat(2,1fr)}main{padding:18px}.mini{grid-template-columns:1fr}h1{font-size:26px}.card strong{font-size:24px}}</style>'''
header='''<header><div class="brands"><div class="pea"><img src="assets/pea-emblem.png" alt="ตราการไฟฟ้าส่วนภูมิภาค"><b>PEA</b></div><img src="assets/sri-trang.png" alt="Sri Trang Group" style="width:110px;height:49px;object-fit:contain"><a class="se" href="https://www.solaredge.com" style="text-decoration:none">solar<span>edge</span></a></div><div class="period">STA-PHS · กันยายน 2569</div></header>'''
