html=html.replace('<section><h2>พลังงานรายวัน','<section id="dailyview"><h2>พลังงานรายวัน',1).replace('<section><h2>ข้อมูลรายชั่วโมง','<section id="hourview"><h2>ข้อมูลรายชั่วโมง',1).replace('<section><h2>ทุกไฟล์และพารามิเตอร์','<section id="filesview"><h2>ทุกไฟล์และพารามิเตอร์',1)
flow='''<section id="overview"><h2>การไหลของพลังงานทั้งเดือน</h2><div class="split"><div class="flowbox" id="flow"></div><div><h3>สัดส่วนการใช้ไฟ</h3><div id="share"></div><p class="data-note">อ้างอิงรายงานพลังงานสะสมกันยายน 2569</p><h3>กำลังไฟตลอดวัน</h3><label>วันที่ <input id="chartdate" type="date" min="2026-09-01" max="2026-09-30" value="2026-09-01"></label><p class="legend">เขียว: โซลาร์ · ม่วง: โหลด · ทอง: ซื้อไฟ</p><div class="scroll"><div class="chartbox"><svg id="powerchart" viewBox="0 0 1000 290" role="img" aria-label="กำลังไฟรายชั่วโมง"></svg></div></div><p id="powercaption" class="data-note"></p></div></div></section>'''
html=html.replace('<section id="dailyview">',flow+'<section id="dailyview">',1)
extras='''<section id="devices"><h2>อินเวอร์เตอร์ 24 เครื่อง</h2><p class="data-note">พลังงานผลิตรายเดือน (kWh) · ไม่จัดอันดับประสิทธิภาพโดยไม่มีขนาดติดตั้งรายเครื่อง</p><div class="scroll"><table id="inverters"></table></div></section><section id="sensors"><h2>มิเตอร์และเซนเซอร์แสง</h2><div class="mini"><div>Import / Export Meter<strong>7B105205_00500</strong><small>CSV ไม่ระบุผู้ผลิตหรือรุ่น Janitza</small></div><div>พลังงานส่งออกเดือนนี้<strong>728.419 kWh</strong><small>0.2664% ของการผลิต</small></div><div>ตรวจข้อมูลมิเตอร์<strong>18 กันยายน</strong><small>Import และ Export = 0 ทั้งวัน</small></div></div><h3>แสงสะสม DIRECT รายวัน</h3><p class="data-note">คงหน่วยต้นทางไว้ หัว CSV ไม่ระบุหน่วย · ไม่ใช่ความเข้มแสง ณ ขณะนั้น (W/m²)</p><svg id="irrchart" viewBox="0 0 1000 290" role="img" aria-label="แสงสะสมรายวัน"></svg><details><summary>ข้อมูลที่มีและข้อมูลที่ต้องเพิ่ม</summary><p>มีแสงสะสม DIRECT / GLOBAL_HORIZONTAL, ค่า Specific Yield, Active Power และ DC Voltage ของ Synergy Unit แบบรายวัน รวมถึงพลังงานและเวลาเดินเครื่องอินเวอร์เตอร์</p><p>GHI เป็นศูนย์ทุกวัน จึงยังไม่ใช้คำนวณ PR ไม่มี THD, PF, Frequency, แรงดัน/กระแส AC หรือ Setpoint การควบคุม Zero Export ในไฟล์ชุดนี้ และยังไม่มีชุดข้อมูลไซต์ TR 500 kVA</p><p>Export ที่พบต้องตรวจร่วมกับ CT, sign convention, deadband และบันทึกการควบคุม ยังไม่สรุปว่า Zero Export ผิดปกติจากยอดสะสมเพียงอย่างเดียว</p></details></section>'''
html=html.replace('<section id="filesview">',extras+'<section id="filesview">',1)
