inv=json.loads(__import__('pandas').read_csv(p/'data/inverter_monthly.csv').to_json(orient='records'))
js='''const INV=__INV__;table('#inverters',['อินเวอร์เตอร์','พลังงานผลิต kWh'],INV.sort((a,b)=>Number(a.inverter.match(/Inverter (\\d+)/)[1])-Number(b.inverter.match(/Inverter (\\d+)/)[1])).map(r=>[esc(r.inverter),fmt(r.energy_kWh)]));document.querySelector('#flow').innerHTML=[['โซลาร์ → อาคาร',s.self_consumed_solar_kWh,'พลังงานที่ผลิตและใช้เอง'],['กริด → อาคาร',s['Imported Energy_kWh'],'พลังงานที่ซื้อจากการไฟฟ้า'],['อาคารใช้ไฟรวม',s['Consumed Energy_kWh'],'โซลาร์ใช้เอง + ซื้อจากกริด'],['โซลาร์ → กริด',s['Exported Energy_kWh'],'พลังงานส่งออกตามรายงานมิเตอร์']].map(([l,v,n])=>`<div class="flowrow">${l}<strong>${fmt(v)} <small>kWh</small></strong><small>${n}</small></div>`).join('');document.querySelector('#share').innerHTML=`<div class="bar"><span style="width:${s.solar_share_pct}%;background:var(--green)"></span><span style="width:${100-s.solar_share_pct}%;background:var(--gold)"></span></div><p>โซลาร์ <b>${fmt(s.solar_share_pct)}%</b> · ซื้อจากกริด <b>${fmt(100-s.solar_share_pct)}%</b></p><p>ใช้โซลาร์เอง <b>${fmt(s.self_consumption_pct)}%</b> ของการผลิต</p>`;function plotPower(){const day=document.querySelector('#chartdate').value;const rows=D.hourly.filter(r=>r.timestamp.startsWith(day));const keys=['Production_mean_kW','Consumption_mean_kW','From Grid_mean_kW'],colors=['#13895b','#74045f','#c7911b'];const max=Math.max(1,...rows.flatMap(r=>keys.map(k=>r[k])));let svg='';for(let i=0;i<=4;i++){let y=240-i*50;svg+=`<line x1="60" y1="${y}" x2="980" y2="${y}" stroke="#e7e8ee"/><text x="4" y="${y+4}" font-size="13" fill="#747988">${fmt(max*i/4)}</text>`}keys.forEach((k,j)=>{let points=rows.map((r,i)=>`${60+i*40},${240-r[k]/max*200}`).join(' ');svg+=`<polyline points="${points}" fill="none" stroke="${colors[j]}" stroke-width="3"/>`;rows.forEach((r,i)=>svg+=`<circle cx="${60+i*40}" cy="${240-r[k]/max*200}" r="3" fill="${colors[j]}"><title>${r.timestamp}: ${fmt(r[k])} kW</title></circle>`)});for(let i=0;i<24;i+=3)svg+=`<text x="${60+i*40}" y="267" font-size="13">${String(i).padStart(2,'0')}:00</text>`;document.querySelector('#powerchart').innerHTML=svg;document.querySelector('#powercaption').textContent='กำลังเฉลี่ยรายชั่วโมง (kW) · '+day+(day==='2026-09-18'?' · ต้องตรวจข้อมูลมิเตอร์: Import = 0 ทั้งวัน':'');}document.querySelector('#chartdate').onchange=()=>{document.querySelector('#date').value=document.querySelector('#chartdate').value;hours();plotPower()};document.querySelector('#date').onchange=()=>{hours();document.querySelector('#chartdate').value=document.querySelector('#date').value;plotPower()};plotPower();let irmax=Math.max(...D.daily.map(r=>r.irradiance_DIRECT_source_units));document.querySelector('#irrchart').innerHTML=D.daily.map((r,i)=>`<rect x="${i*31+40}" y="${245-r.irradiance_DIRECT_source_units/irmax*205}" width="20" height="${r.irradiance_DIRECT_source_units/irmax*205}" fill="#c7911b"><title>${r.date}: ${fmt(r.irradiance_DIRECT_source_units)} (หน่วยต้นทาง)</title></rect><text x="${i*31+40}" y="269" font-size="12">${i+1}</text>`).join('');'''
html=html.replace('</script>',js.replace('__INV__',json.dumps(inv,ensure_ascii=False))+'</script>',1)
